import {layout} from './layout.js';
const $=s=>document.querySelector(s),mode=document.body.dataset.tool;
let images=[],pages=[],seq=0,busy=false,token=0,worker=null;
const status=(s,error=false)=>{const e=$('#status');if(e){e.textContent=s;e.classList.toggle('error',error)}};
const tick=()=>new Promise(r=>setTimeout(r,0));
function options(){const o={};document.querySelectorAll('[data-option]').forEach(e=>o[e.id]=e.type==='checkbox'?e.checked:e.type==='number'?Number(e.value):e.value);return o}
function validate(){for(const e of document.querySelectorAll('[data-option]'))if(!e.checkValidity())throw Error(`Check the “${e.closest('label')?.childNodes[0]?.textContent.trim()||e.id}” field.`)}
function setBusy(v){busy=v;$('#cancel').disabled=!v;$('#download').disabled=v||!pages.length;$('#files').disabled=v;$('#refresh').disabled=v;document.querySelectorAll('[data-option],.photo button,.photo input').forEach(e=>e.disabled=v)}
function renderList(){const list=$('#photos');list.replaceChildren();images.forEach((im,i)=>{const li=document.createElement('li');li.className='photo';li.draggable=true;li.dataset.id=im.id;const thumb=document.createElement('img');thumb.src=im.data;thumb.alt='';thumb.draggable=false;const name=document.createElement('span');name.className='name';name.textContent=`${i+1}. ${im.name} · ${im.w}×${im.h}`;li.append(thumb,name);const actions=document.createElement('div');actions.className='actions';const add=(txt,fn)=>{const b=document.createElement('button');b.type='button';b.textContent=txt;b.onclick=fn;actions.append(b)};add('↑ Move up',()=>move(i,i-1));add('↓ Move down',()=>move(i,i+1));if(mode==='arrange'){add('Duplicate',()=>{if(images.length>=30)return status('You can add up to 30 images.',true);images.splice(i+1,0,{...im,id:++seq});renderList();refresh()});const label=document.createElement('label');label.textContent='Copies ';const input=document.createElement('input');Object.assign(input,{type:'number',min:'1',max:'30',value:im.copies});input.setAttribute('aria-label',`Copies of ${im.name}`);input.onchange=()=>{im.copies=Number(input.value);refresh()};label.append(input);actions.append(label)}add('Remove',()=>{images.splice(i,1);renderList();refresh()});li.append(actions);li.ondragstart=e=>{e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',String(im.id))};li.ondragover=e=>e.preventDefault();li.ondrop=e=>{e.preventDefault();const from=images.findIndex(x=>String(x.id)===e.dataTransfer.getData('text/plain'));if(from>=0)move(from,i)};list.append(li)})}
function move(a,b){if(b<0||b>=images.length)return;const [im]=images.splice(a,1);images.splice(b,0,im);renderList();refresh()}
async function loadFiles(files){if(busy)return;setBusy(true);const t=++token;let errors=[],added=0;try{for(const file of files){if(t!==token)break;if(mode!=='arrange'&&added)break;if(images.length>=30&&mode==='arrange'){errors.push('You can add up to 30 images.');break}if(!/\.(jpe?g|png|webp)$/i.test(file.name)||!['image/jpeg','image/png','image/webp'].includes(file.type)){errors.push(`${file.name}: Unsupported image format. Choose JPG, PNG or WebP.`);continue}if(file.size>20*1024*1024){errors.push(`${file.name}: The file exceeds 20 MiB. Use a smaller file.`);continue}let bitmap;try{bitmap=await createImageBitmap(file,{imageOrientation:'from-image'});if(bitmap.width*bitmap.height>12000000)throw Error('The image exceeds 12 megapixels. Resize it first.');const used=(mode==='arrange'?images:[]).reduce((n,x)=>n+x.w*x.h,0);if(used+bitmap.width*bitmap.height>32000000)throw Error('Images exceed 32 megapixels in total (about 128 MB for decoded pixels alone). Remove or resize some images.');if(t!==token)break;const c=document.createElement('canvas');c.width=bitmap.width;c.height=bitmap.height;c.getContext('2d').drawImage(bitmap,0,0);const data=c.toDataURL('image/png');if((mode==='arrange'?images:[]).reduce((n,x)=>n+x.data.length*.75,0)+data.length*.75>80*1024*1024)throw Error('Normalized images exceed 80 MiB in total. Remove or resize some images.');const el=new Image();el.src=data;await el.decode();if(t!==token)break;const im={id:++seq,name:file.name,w:c.width,h:c.height,data,el,copies:1};if(mode==='arrange')images.push(im);else images=[im];added++}catch(e){errors.push(`${file.name}: Could not open this image. ${e.message}`)}finally{bitmap?.close()}await tick()}}finally{if(t===token){setBusy(false);renderList();refresh();if(errors.length)status(errors.join(' '),true);$('#files').value=''}}}
function refresh(){pages=[];$('#previews').replaceChildren();try{validate();if(!images.length){$('#previews').innerHTML='<p class="empty">Add images to preview your pages here.<br>Your files stay on your device.</p>';$('#page-count').textContent='No pages yet';return}for(const im of images)if(!Number.isInteger(im.copies)||im.copies<1||im.copies>30)throw Error('Copies must be a whole number from 1 to 30.');pages=layout(mode,options(),images);let low=false;pages.forEach((p,i)=>{const fig=document.createElement('figure');fig.className='sheet';const c=document.createElement('canvas');const scale=360/p.w;c.width=360;c.height=Math.round(p.h*scale);const ctx=c.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,c.width,c.height);ctx.scale(scale,scale);for(const it of p.items){const im=images.find(x=>x.id===it.id);ctx.save();ctx.beginPath();ctx.rect(it.clip.x,it.clip.y,it.clip.w,it.clip.h);ctx.clip();ctx.drawImage(im.el,it.x,it.y,it.w,it.h);ctx.restore();if(im.w/(it.w/25.4)<150||im.h/(it.h/25.4)<150)low=true;if(mode==='size'){ctx.save();ctx.setLineDash([1,1]);ctx.strokeStyle='#72847b';ctx.lineWidth=.25;ctx.strokeRect(it.clip.x,it.clip.y,it.clip.w,it.clip.h);ctx.restore()}}ctx.strokeStyle='black';ctx.lineWidth=.15;for(const m of p.marks){ctx.beginPath();ctx.moveTo(m.x1,m.y1);ctx.lineTo(m.x2,m.y2);ctx.stroke()}const caption=document.createElement('figcaption');caption.textContent=`Page ${i+1} of ${pages.length}${p.label?' · Row / column: '+p.label:''} · ${p.w} × ${p.h} mm`;c.setAttribute('aria-label',caption.textContent);fig.append(c,caption);$('#previews').append(fig)});$('#page-count').textContent=`${pages.length} page${pages.length === 1 ? "" : "s"}`;status(low?'Resolution warning: some images are below 150 PPI at this print size and may look pixelated.':'Preview ready. Print at 100% or Actual size to keep the dimensions.');if($('#remember').checked){try{localStorage.setItem('ratteb-preferences',JSON.stringify(options()))}catch{status('Could not save preferences. You can continue without saving.',true)}}}catch(e){pages=[];status(e.message,true);$('#page-count').textContent='Check your settings'}finally{$('#download').disabled=busy||!pages.length}}
function download(){if(!pages.length||busy)return;setBusy(true);status('Creating your PDF… You can cancel.');worker=new Worker('assets/pdf-worker.js');worker.onmessage=({data})=>{if(data.error){status('PDF export failed: '+data.error,true);finish()}else if(data.bytes){const blob=new Blob([data.bytes],{type:'application/pdf'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`ratteb-${mode}.pdf`;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);status('PDF created and downloaded. Choose Actual size when printing.');finish()}else status(`Creating PDF: ${data.progress} of ${pages.length}`)};worker.onerror=()=>{status('Could not start PDF export. Check that all site files loaded, then try again.',true);finish()};worker.postMessage({pages,images:images.map(({id,data})=>({id,data}))})}
function finish(){worker?.terminate();worker=null;setBusy(false)}
if(mode){$('#files').addEventListener('change',e=>loadFiles([...e.target.files]));$('#refresh').onclick=refresh;$('#download').onclick=download;$('#cancel').onclick=()=>{++token;finish();renderList();refresh();status('Canceled. No new file was created.');};document.querySelectorAll('[data-option]').forEach(e=>e.addEventListener('change',refresh));$('#remember').onchange=e=>{if(e.target.checked)refresh();else try{localStorage.removeItem('ratteb-preferences')}catch{}};$('#clear-preferences').onclick=()=>{try{localStorage.removeItem('ratteb-preferences');$('#remember').checked=false;status('Saved preferences cleared.')}catch{status('Could not access local storage.',true)}};try{const saved=JSON.parse(localStorage.getItem('ratteb-preferences')||'null');if(saved){for(const [k,v]of Object.entries(saved)){const e=document.getElementById(k);if(e?.hasAttribute('data-option')){if(e.type==='checkbox')e.checked=!!v;else e.value=v}}$('#remember').checked=true}}catch{}refresh()}
const contact=$('#contact-address');if(contact&&window.SITE_CONFIG?.email){const a=document.createElement('a');a.href='mailto:'+window.SITE_CONFIG.email;a.textContent=window.SITE_CONFIG.email;contact.replaceChildren(a)}
$('#print-ruler')?.addEventListener('click',()=>window.print());
